"""Build a full custom training session and preserve it across saving, PDF and reload."""
from playwright.sync_api import sync_playwright
import subprocess
with sync_playwright() as p:
 b=p.chromium.launch(executable_path='/usr/bin/chromium',args=['--no-sandbox']);page=b.new_page(viewport={'width':1440,'height':1100});errors=[];page.on('pageerror',lambda e:errors.append(str(e)));page.on('dialog',lambda d:d.accept());page.goto('http://127.0.0.1:3016/?mode=local');page.locator('#view-training').click();page.locator('#training-duration').fill('60');page.locator('#training-step-link-2').click();page.locator('#training-players').fill('16');page.locator('#training-keepers').fill('2');page.select_option('#training-space-size','quarter');page.locator('#training-step-link-1').click();page.locator('#training-manual').click()
 assert page.evaluate('currentTraining.creationMode')=='manual';assert page.evaluate('currentTraining.blocks.length')==0;assert page.locator('#local-coach-propose').is_hidden();page.locator('#training-step-link-0').click();page.locator('#training-title').fill('Séance libre du coach');page.locator('#training-step-link-3').click()
 for i in range(2):
  page.locator('#training-custom-add').click();page.locator('#custom-training-title').fill(['Activation libre','Pressing inventé'][i]);page.locator('#custom-training-duration').fill('20');page.select_option('#custom-training-kind',['circuit','game'][i]);page.locator('#custom-training-goal').fill('Progresser ensemble');page.locator('#custom-training-organisation').fill('Deux équipes et rotations');page.locator('#custom-training-instructions').fill('Garder les distances\nRéagir ensemble');page.locator('#custom-training-material').fill('Ballons et coupelles');page.locator('#custom-training-success').fill('Trois récupérations coordonnées');page.locator('#custom-training-form button[type=submit]').click()
 assert page.locator('#training-blocks .training-block').count()==2;assert '20 min à répartir' in page.locator('#training-remaining').inner_text();assert page.locator('#training-blocks .training-diagram-screen svg').first.get_attribute('data-players')=='16'
 page.locator('#training-blocks .training-block').nth(1).get_by_role('button',name='Monter cet exercice').click();assert page.evaluate('currentTraining.blocks[0].custom.title')=='Pressing inventé'
 page.locator('#training-blocks .training-block').first.get_by_role('button',name='Modifier mon exercice').click();page.locator('#custom-training-instructions').fill('Fermer l’axe puis presser');page.locator('#custom-training-form button[type=submit]').click();assert page.evaluate('currentTraining.blocks[0].custom.instructions')=='Fermer l’axe puis presser'
 # Add a catalogue exercise and adjust to the exact session duration.
 page.locator('#training-catalogue-toggle').click();page.locator('#training-catalogue .training-catalogue-card').first.get_by_role('button',name='+ Ajouter à la séance',exact=True).click();page.locator('#training-blocks .training-block').last.locator('input[type=number]').fill('20');page.locator('#training-step-title-3').click();assert page.evaluate('trainingTotal()')==60;assert 'Durée prévue atteinte' in page.locator('#training-remaining').inner_text()
 page.locator('#training-save').click();saved=page.evaluate('structuredClone(currentTraining)');assert page.evaluate('trainingValid(currentTraining)');page.reload();page.locator('#view-training').click();assert page.evaluate('currentTraining.blocks')==saved['blocks'];assert page.locator('#training-space-size').input_value()=='quarter';assert page.evaluate('trainingLibrary.length')==1
 # Print retains custom content and the selected space.
 page.evaluate('window.print=()=>{}');page.locator('#training-pdf').click();page.emulate_media(media='print');page.pdf(path='/tmp/seance-libre-coach.pdf',prefer_css_page_size=True,print_background=True);text=subprocess.check_output(['pdftotext','/tmp/seance-libre-coach.pdf','-'],text=True);assert 'Pressing inventé' in text;assert 'Fermer' in text;assert 'Quart de terrain' in text;assert '16 joueurs' in text;page.emulate_media(media='screen');page.evaluate('document.body.classList.remove("training-printing")')
 assert not page.evaluate('trainingValid({...currentTraining,blocks:[{id:"bad",exerciseId:"custom",duration:10,notes:"",custom:{title:"Incomplete"}}]})')
 # All three requested surfaces are retained and recompute the organisation.
 page.locator('#training-step-link-2').click()
 for space in ['full','half','quarter']:page.select_option('#training-space-size',space);assert page.evaluate('currentTraining.space')==space
 page.locator('#training-step-link-3').click();page.set_viewport_size({'width':390,'height':844});page.locator('#training-custom-add').click();assert page.locator('#custom-training-dialog').evaluate('(e)=>e.scrollWidth<=e.clientWidth');assert page.evaluate('document.documentElement.scrollWidth<=innerWidth');assert not errors,errors
 print('PASS: manual session, players/duration/quarter pitch, own exercise details/edit/reorder, mixed catalogue, diagrams, duration balance, library/reload, printable PDF, schema validation, all surfaces and mobile.')
 b.close()
